type LayoutSchemaVersion = 2;
type Breakpoint = 'desktop' | 'tablet' | 'mobile';

interface GridConfig {
  columns: number;
  rowHeight: number;
  gap: number;
}

interface WidgetLayout {
  id: string;
  x: number;
  y: number;
  width: number;
  height: number;
  minWidth: number;
  minHeight: number;
}

interface DashboardSnapshot {
  schemaVersion: LayoutSchemaVersion;
  revision: number;
  layouts: Partial<Record<Breakpoint, WidgetLayout[]>>;
  updatedAt: string;
}

interface InteractionState {
  activeId: string | null;
  mode: 'idle' | 'drag' | 'resize' | 'keyboard-move' | 'keyboard-resize';
  baseRevision: number;
  startRect?: WidgetLayout;
  candidateRect?: WidgetLayout;
}

interface PendingLayout {
  commandId: string;
  basedOnRevision: number;
  breakpoint: Breakpoint;
  patch: WidgetLayout[];
}
